import { useEffect, useState } from "react";
import API from "../services/api";
import "./Historial.css";

function HistorialCompras(){

 const [historial,setHistorial] = useState([]);
 const [filtro,setFiltro] = useState("");

 const usuario = JSON.parse(localStorage.getItem("usuario"));

 useEffect(()=>{
  cargarHistorial();
 },[]);


 const cargarHistorial = async ()=>{

  try{

   const res = await API.get(`/historialCompras/${usuario.id_usuario}`);

   setHistorial(res.data);

  }catch(error){

   console.log(error);

  }

 };


 // ======================
 // FILTRO
 // ======================

 const filtrados = historial.filter(p =>
  p.tipo_producto.toLowerCase().includes(filtro.toLowerCase()) ||
  p.color.toLowerCase().includes(filtro.toLowerCase()) ||
  (p.fecha_compra && p.fecha_compra.includes(filtro))
 );


 return(

  <div className="historial-container">

   <h2>Historial de Compras</h2>

   <input
    type="text"
    placeholder="Buscar por nombre, color o fecha..."
    value={filtro}
    onChange={(e)=>setFiltro(e.target.value)}
    className="input-busqueda"
   />


   <div className="grid">

    {filtrados.map((p)=>(
     
     <div className="card" key={p.id_producto}>

      <img
       src={`http://192.168.1.9:3000/uploads/${p.imagen}`}
       alt=""
      />

      <h3>{p.tipo_producto}</h3>

      <p>Color: {p.color}</p>
      <p>Peso: {p.peso} ct</p>

      <h2>${p.valor}</h2>

      <p className="fecha">
       📅 {p.fecha_compra}
      </p>

      <p className="estado">
       ✅ Comprado
      </p>

     </div>

    ))}

   </div>

  </div>

 );

}

export default HistorialCompras;
